'use strict';
(()=>{
const D=window.KV_CONTENT,P=window.KV_PIXEL.createPixelArt(D,document),F=P.schoolFX,$=s=>document.querySelector(s),skills=id=>D.skills.filter(s=>s.class_id===id).sort((a,b)=>a.slot-b.slot);
let classId='kiem',slot=0,compare=false,compareIndex=7,playing=true,elapsed=.55,previous=performance.now(),levelStart=-Infinity,levelHold=false;
const levelAge=()=>levelHold?.6:(performance.now()-levelStart)/1000;
function cancelLevel(){levelHold=false;levelStart=-Infinity;}
const stage=$('#effectStage'),ctx=stage.getContext('2d');
function init(){
 $('#schoolTabs').innerHTML=D.classes.map(c=>`<button data-school="${c.class_id}" aria-pressed="${c.class_id===classId}">${c.class_name}</button>`).join('');
 $('#comparisonGrid').innerHTML=D.classes.map(c=>`<article class="fx-comparison-card"><header><b>${c.class_name}</b><small>${F.schools[c.class_id].theme}</small></header><canvas width="300" height="180" data-stage-school="${c.class_id}" aria-label="Hiệu ứng ${c.class_name}"></canvas><footer data-stage-caption="${c.class_id}"></footer></article>`).join('');renderSelection();
}
function renderSelection(){const list=skills(classId),sk=list[slot],v=F.visual(sk),def=F.schools[classId];$('#fxSchoolPortrait').innerHTML=P.classPortrait(classId);$('#fxClass').textContent=def.name;$('#fxTheme').textContent=def.theme;$('#fxMotif').textContent=v.label;$('#selectedSkill').textContent=sk.skill_name;$('#fxMechanic').textContent=({cone:'Chém hình quạt',dash:'Lướt đánh',proj:'Đạn bay',rain:'Mưa đạn',circle:'Chiêu quanh vùng',chain:'Liên kích qua mục tiêu',buff:'Tăng chỉ số',heal:'Hồi phục',shield:'Hộ thể',summon:'Triệu hồi',ult:'Tuyệt kỹ'}[sk.mechanic_type]||'Kỹ năng')+' · '+sk.mana_cost+' nội lực · Hồi '+sk.cooldown_seconds+' giây';$('#skillChoices').innerHTML=list.map((s,i)=>`<button data-book-skill="${i}" aria-pressed="${slot===i}">${P.skillIcon(s)}<span><strong>${i+1}. ${s.skill_name}</strong><small>${F.visual(s).label}</small></span></button>`).join('');document.querySelectorAll('[data-school]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.school===classId)));for(const c of D.classes)document.querySelector(`[data-stage-caption="${c.class_id}"]`).textContent=skills(c.class_id)[compareIndex].skill_name;}
function backdrop(c,w,h){c.imageSmoothingEnabled=false;c.fillStyle='#102532';c.fillRect(0,0,w,h);c.strokeStyle='#294651';c.lineWidth=1;for(let x=0;x<w;x+=32){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=24){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}c.fillStyle='#1c3c45';c.fillRect(0,h*.73,w,h*.27);c.fillStyle='#5c7267';c.fillRect(0,h*.73,w,2);}
function scene(c,id,idx,w,h,time,small=false){backdrop(c,w,h);const sk=skills(id)[idx],v=F.visual(sk),hero={x:w*.4,y:h*.75},target={x:w*.65,y:h*.7},scale=small?.56:1; c.save();if(small){c.translate(w*.5,h*.59);c.scale(.65,.65);c.translate(-w*.5,-h*.59);}const hx=small?w*.35:hero.x,hy=hero.y,tx=small?w*.72:target.x,ty=target.y;hero.x=hx;hero.y=hy;P.hero(c,id,hx,hy,{scale:small?.7:1,attack:time<.45?Math.ceil((.5-time)*6):0});if(!small)P.creature(c,{dummy:true,x:tx,y:ty,dir:1,walk:0});const levelTime=levelAge();if(levelTime<2.52){F.level(c,{max:2.52,life:2.52-levelTime},hero);c.restore();return;}
 const t=Math.min(2.18,time),area=['circle','rain','ult','chain'].includes(sk.mechanic_type)&&sk.mechanical_parameters?.target_anchor!=='self',x=area?tx:hx,y=area?ty:hy;F.draw(c,{kind:'schoolCast',x,y,r:small?112:125,angle:0,max:2.2,life:2.2-t,visual:v},hero);
 if(['shield','buff'].includes(sk.mechanic_type))F.draw(c,{kind:'schoolAura',x:hx,y:hy,r:40,max:2.2,life:2.2-t,visual:v},hero);
 if(sk.mechanic_type==='chain')F.draw(c,{kind:'schoolLink',x:hx,y:hy,tx,ty,max:2.2,life:2.2-t,visual:v},hero);
 if(sk.mechanic_type==='proj')F.projectile(c,{x:hx+(tx-hx)*(t/2.2),y:hy+(ty-hy)*(t/2.2),vx:1,vy:0,visual:v});
 if(sk.mechanic_type==='dash')F.draw(c,{kind:'schoolDash',x:hx-55,y:hy,tx:hx+100,ty:hy,r:60,angle:0,max:2.2,life:2.2-t,visual:v},hero);
 c.restore();}
function draw(){if(compare){for(const cv of document.querySelectorAll('[data-stage-school]'))scene(cv.getContext('2d'),cv.dataset.stageSchool,compareIndex,cv.width,cv.height,elapsed,true);}else scene(ctx,classId,slot,stage.width,stage.height,elapsed);$('#frameTime').textContent=elapsed.toFixed(2)+'s';const lt=levelAge();$('#levelBanner').hidden=lt>=2.52;if(lt<2.52)F.rays($('#levelRays').getContext('2d'),lt);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.school){cancelLevel();classId=b.dataset.school;elapsed=.55;renderSelection();}if(b.dataset.bookSkill!==undefined){cancelLevel();slot=Number(b.dataset.bookSkill);elapsed=.55;renderSelection();}if(b.id==='compareToggle'){cancelLevel();compare=!compare;document.body.classList.toggle('is-comparing',compare);$('#compareView').hidden=!compare;$('#singleView').hidden=compare;b.setAttribute('aria-pressed',String(compare));b.textContent=compare?'Xem từng phái':'So sánh 14 phái';}if(b.id==='playFx'){playing=!playing;if(playing&&levelHold){levelHold=false;levelStart=performance.now();$('#levelBanner').classList.add('celebrating');}}if(b.id==='midFrame'){playing=false;elapsed=.75;if(levelAge()<2.52){levelHold=true;$('#levelBanner').classList.remove('celebrating');}}if(b.id==='levelPreview'){levelStart=performance.now();levelHold=!playing;$('#selectedSkill').textContent='Xem hiệu ứng lên cấp · không đổi cấp';const el=$('#levelBanner');el.classList.remove('celebrating');void el.offsetWidth;el.hidden=false;if(!levelHold)el.classList.add('celebrating');}$('#playFx').textContent=playing?'Tạm dừng':'Phát hiệu ứng';$('#playFx').setAttribute('aria-pressed',String(playing));draw();});
$('#compareSlot').addEventListener('change',e=>{cancelLevel();compareIndex=Number(e.target.value);renderSelection();draw();});
init();function frame(now){const dt=Math.min(.05,(now-previous)/1000);previous=now;if(playing){elapsed=(elapsed+dt)%2.2;draw();}else if(!levelHold&&levelAge()<2.52)draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
})();
